// Deterministic keyword-based grading of an agent answer. No LLM judge -
// consistent with the rest of this project, and free to run repeatedly.
const row = $('Map eval row to chat input').first().json;
const answer = String($json.output || $json.text || '');

const pattern = row.expected_keywords ? new RegExp(row.expected_keywords, 'i') : null;
const keywordHit = pattern ? (pattern.test(answer) ? 1 : 0) : null;

const chartPresent = /quickchart\.io\/chart/.test(answer) ? 1 : 0;
const saidCouldNotRetrieve = /couldn.t retrieve|no reliable knowledge/i.test(answer);

return [{ json: {
  id: row.id,
  category: row.category,
  keyword_hit: keywordHit,
  chart_present: chartPresent,
  said_could_not_retrieve: saidCouldNotRetrieve ? 1 : 0,
  answer_length: answer.length,
  answer_preview: answer.slice(0, 200),
}}];
